INSERT INTO public.adrstreet (name, postalcode, localityid, name_ro, street_type_ro)
SELECT s.name_ro, s.postalcode, l.id, s.name_ro, s.type_ro
FROM _adr_street_staging s
JOIN public.adrlocality l ON l.siruta_code = s.siruta_code
ON CONFLICT DO NOTHING;

DROP TABLE _adr_street_staging;

COMMIT;
